+  <meta charset="UTF-8" />
+  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
+  <title>Cat FAQ</title>
+  <style>
+    :root {
+      color-scheme: dark;
+      --bg: #0b0f14;
+      --panel: #111823;
+      --panel-2: #151e2b;
+      --text: #e7edf6;
+      --muted: #9dadc3;
+      --accent: #7cc4ff;
+      --accent-2: #9b87ff;
+      --border: rgba(148, 163, 184, 0.16);
+      --shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
