  <style>
    :root {
      color-scheme: dark;
      --bg: #0b0f14;
      --panel: #111823;
      --panel-2: #151e2b;
      --text: #e7edf6;
      --muted: #9dadc3;
      --accent: #7cc4ff;
      --accent-2: #9b87ff;
      --border: rgba(148, 163, 184, 0.16);
      --shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 196, 255, 0.16), transparent 34%),
        radial-gradient(circle at bottom right, rgba(155, 135, 255, 0.14), transparent 28%),
        var(--bg);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 32px 16px;
    }

