      width: min(840px, 100%);
    }

    .card {
      background: linear-gradient(180deg, rgba(21, 30, 43, 0.96), rgba(13, 19, 28, 0.96));
      border: 1px solid var(--border);
      border-radius: 24px;
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .hero {
      padding: 32px 32px 18px;
      border-bottom: 1px solid var(--border);
    }

    .eyebrow {
      margin: 0 0 10px;
      color: var(--accent);
      letter-spacing: 0.18em;
      text-transform: uppercase;
      font-size: 0.78rem;
      font-weight: 700;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 3vw, 3rem);
      line-height: 1.05;
    }

    .subtitle {
      margin: 14px 0 0;
      color: var(--muted);
      max-width: 62ch;
      line-height: 1.6;
    }

    .faq {
      padding: 14px;
      display: grid;
      gap: 12px;
    }

    .example {
      background: linear-gradient(180deg, rgba(17, 24, 35, 0.92), rgba(12, 17, 26, 0.92));
      border: 1px solid var(--border);
      border-radius: 18px;
      overflow: hidden;
    }

    .question {
      width: 100%;
      border: 0;
      background: transparent;
      color: var(--text);
      text-align: left;
      padding: 20px 22px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
      font: inherit;
      cursor: pointer;
    }

    .question:hover {
      background: rgba(124, 196, 255, 0.05);
    }

    .question:focus-visible {
      outline: 2px solid var(--accent);
      outline-offset: -2px;
    }

    .question-text {
      font-size: 1.05rem;
      font-weight: 650;
      line-height: 1.35;
    }

    .chevron {
      flex: 0 0 auto;
      width: 40px;
      height: 40px;
      border-radius: 50%;
      display: grid;
      place-items: center;
      background: rgba(124, 196, 255, 0.08);
      color: var(--accent);
      transition: transform 0.2s ease, background 0.2s ease;
    }

    .details {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.28s ease;
      border-top: 1px solid transparent;
    }

    .details-inner {
      padding: 0 22px 20px;
      color: var(--muted);
      line-height: 1.7;
    }

    .example.open .details {
      border-top-color: var(--border);
    }

    .example.open .chevron {
      transform: rotate(180deg);
      background: rgba(124, 196, 255, 0.14);
    }

    .example.open .details {
      max-height: 220px;
    }

    @media (max-width: 640px) {
      .hero {
        padding: 24px 20px 16px;
      }

      .faq {
        padding: 10px;
      }

      .question,
      .details-inner {
        padding-left: 18px;
        padding-right: 18px;
      }
    }
  </style>
</head>
<body>
  <main>
    <section class="card" aria-labelledby="faq-title">
      <header class="hero">
        <p class="eyebrow">Frequently asked questions</p>
        <h1 id="faq-title">Cats, answered</h1>
        <p class="subtitle">A compact FAQ with polished dark styling. Tap any question to reveal the answer.</p>
      </header>

      <div class="faq" id="faq">
        <div class="example">
          <button class="question" type="button" aria-expanded="false">
            <span class="question-text">Why do cats purr?</span>
            <span class="chevron" aria-hidden="true">⌄</span>
          </button>
          <div class="details" hidden>
            <div class="details-inner">
              Cats purr for comfort, communication, and sometimes self-soothing. It is often a sign that they feel safe, relaxed, or are asking for attention.
            </div>
          </div>
        </div>

        <div class="example">
          <button class="question" type="button" aria-expanded="false">
            <span class="question-text">How much sleep do cats need?</span>
            <span class="chevron" aria-hidden="true">⌄</span>
          </button>
          <div class="details" hidden>
            <div class="details-inner">
              Most cats sleep between 12 and 16 hours a day, and kittens or senior cats may sleep even more. Their energy tends to come in short, playful bursts.
            </div>
          </div>
        </div>

        <div class="example">
          <button class="question" type="button" aria-expanded="false">
            <span class="question-text">Do cats need indoor enrichment?</span>
            <span class="chevron" aria-hidden="true">⌄</span>
          </button>
          <div class="details" hidden>
            <div class="details-inner">
              Yes. Scratching posts, climbing spots, toys, and window views help keep cats mentally and physically engaged, especially in indoor homes.
            </div>
          </div>
        </div>

        <div class="example">
          <button class="question" type="button" aria-expanded="false">
            <span class="question-text">Why do cats knead blankets?</span>
            <span class="chevron" aria-hidden="true">⌄</span>
          </button>
          <div class="details" hidden>
            <div class="details-inner">
              Kneading is a comforting behavior linked to kittenhood. Cats often do it when they feel content, settled, or especially affectionate.
            </div>
          </div>
        </div>
      </div>
    </section>
  </main>

  <script>
    const examples = document.querySelectorAll('.example');

    examples.forEach((example) => {
      const button = example.querySelector('.question');
      const details = example.querySelector('.details');

      button.addEventListener('click', () => {
        const isOpen = example.classList.toggle('open');
        button.setAttribute('aria-expanded', String(isOpen));

        if (isOpen) {
          details.hidden = false;
          details.style.maxHeight = `${details.scrollHeight}px`;
        } else {
          details.style.maxHeight = '0px';
          window.setTimeout(() => {
            if (!example.classList.contains('open')) {
              details.hidden = true;
            }
          }, 280);
        }
      });
    });
  </script>
</body>
</html>
